// Writes rust/tearout-dsp/src/spec.rs from the gun engine's SPEC (globals, samples, gun groups).
import { writeFileSync } from 'fs';
import { SPEC, inEngine } from '../dsp/engine.js';
const S = SPEC.filter((s) => inEngine(s, 'gun') && s.id !== 'engine');
const num = (v) => (Number.isInteger(v) ? v.toFixed(1) : String(v));
const str = (v) => JSON.stringify(v ?? '');
const lines = [
  '// Generated by fit/gen_rust_spec.js from dsp/engine.js. Edit the JS spec and regenerate.',
  '#[derive(Clone, Copy, Debug, PartialEq)]',
  'pub enum Scale { Lin, Log, Int }',
  '#[derive(Clone, Copy, Debug)]',
  'pub struct Spec { pub id: &\'static str, pub group: &\'static str, pub label: &\'static str, pub min: f64, pub max: f64, pub def: f64, pub scale: Scale, pub unit: &\'static str, pub fit: bool }',
  `pub const N: usize = ${S.length};`,
  'pub const SPEC: [Spec; N] = [',
  ...S.map((s) => `  Spec { id: ${str(s.id)}, group: ${str(s.g)}, label: ${str(s.label)}, min: ${num(s.min)}, max: ${num(s.max)}, def: ${num(s.def)}, scale: Scale::${{ lin: 'Lin', log: 'Log', int: 'Int' }[s.scale || 'lin']}, unit: ${str(s.unit)}, fit: ${s.fit !== false} },`),
  '];',
  '#[allow(dead_code)]',
  'pub mod id {',
  ...S.map((s, i) => `  pub const ${s.id.toUpperCase()}: usize = ${i};`),
  '}',
];
writeFileSync('rust/tearout-dsp/src/spec.rs', lines.join('\n') + '\n');
console.log(S.length, 'params');
